import {test} from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';import {Vec2,Box} from 'planck';import {CPUController} from '../server/cpu';import {session} from '../scripts/bot-b2-harness';import {herd,opening} from '../scripts/bot-b2i-bench';import {tacticalState} from '../server/strategy/state';
test('personality is seeded, stable through resets, independent of cosmetics and separate from difficulty',()=>{const xs=Array.from({length:8},(_,i)=>new CPUController(23+i*239)),profiles=xs.map(c=>c.tactics.preferences);assert.equal(new Set(profiles.map(p=>JSON.stringify(p))).size,8);profiles.forEach((p,i)=>{assert.ok(Object.isFrozen(p));assert.deepEqual(p,new CPUController(23+i*239).tactics.preferences);xs[i].reset();assert.equal(xs[i].tactics.preferences,p);});assert.ok(new Set(profiles.map(p=>p.cadence+':'+p.phase)).size>=6);});
test('initial tactical goal is immediate, no pre-countdown inputs, and subsequent decisions have independent phases',()=>{for(const mode of['poison','freeze','classic']as const){const s=session(mode,8);const state=tacticalState(s.rules.view(0));s.cs.forEach((c,i)=>{for(let t=0;t<20;t++)assert.deepEqual(c.input(s.sim.frogs[i],t,false,false,false,s.sim,{...state,phase:'countdown'}),{x:0,y:0,held:false});assert.equal(c.tactics.stats.decisions,0);c.input(s.sim.frogs[i],0,true,false,false,s.sim,state);assert.equal(c.tactics.stats.decisions,1);assert.ok(c.navigation.goal);});assert.ok(new Set(s.cs.map(c=>(c.tactics as any).next)).size>=4);}});
test('multiple hunters diversify viable targets, but converge legitimately when only one is eligible',()=>{let before=0,after=0;for(let i=0;i<20;i++){const seed=23+i*239,a=herd(true,seed),b=herd(false,seed);before+=a.sameTarget;after+=b.sameTarget;assert.ok(b.targets.every(t=>t!==undefined&&t>=5));}assert.ok(after<before*.8);assert.equal(herd(false,23,true).uniqueTargets,1);assert.equal(herd(false,23,true).targets[0],7);});
test('opening movement is reproducible and runners choose several viable destinations',()=>{const a=opening(false,'poison','sunny-pond',8,23),b=opening(false,'poison','sunny-pond',8,23);assert.deepEqual(a,b);assert.ok(a.first.every(x=>x!==null&&x<=.5));assert.ok(a.goalsAtStart.every(Boolean));assert.ok(new Set(a.goalsAtStart.slice(1).map(p=>Math.round(p!.x/2)+':'+Math.round(p!.y/2))).size>=3);});
test('unrelated poison conversion does not erase an ongoing hunter target commitment',()=>{const s=session('poison',8),c=s.cs[0];c.input(s.sim.frogs[0],0,true,false,false,s.sim,tacticalState(s.rules.view(0)));const until=(c.tactics as any).committedUntil;assert.ok(until>0);(s.rules.records[6]as any).infectedTick=1;(s.rules.records[6]as any).infectiousTick=61;s.sim.tick=1;c.input(s.sim.frogs[0],1,true,false,false,s.sim,tacticalState(s.rules.view(1)));assert.equal((c.tactics as any).committedUntil,until);});
test('corrected B1 navigator, spring recovery, bubble presses, human systems and rules stay byte-identical',()=>{const m=JSON.parse(readFileSync('docs/bot-b2i-preservation.json','utf8')),hash=(x:any)=>createHash('sha256').update(x).digest('hex');for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(readFileSync(p)),r.afterSha256,p);}for(const[p,h]of Object.entries(m.protected))assert.equal(hash(readFileSync(p)),h,p);const source=readFileSync('server/strategy/tactics.ts','utf8');assert.doesNotMatch(source,/setTransform|setLinearVelocity|applyForce|applyLinearImpulse|\.infect\(|\.launch\(|\.fire\(/);assert.doesNotMatch(source,/\.tactics\.|\.navigation\.|cpuOrder|appearance|skin/);});

test('equal-distance tactical choices vary independently without peer-goal access',()=>{const chosen=new Set<number>();for(let seed=1;seed<=20;seed++){const s=session('poison',3,'sunny-pond',seed);for(let b=s.sim.world.getBodyList();b;){const next=b.getNext();if(!s.sim.frogs.some(f=>f.body===b))s.sim.world.destroyBody(b);b=next;}s.sim.world.createBody(Vec2(20,20)).createFixture(Box(20,.5));s.sim.frogs.forEach((f,i)=>f.body.setTransform(Vec2([20,13,27][i],19),0));s.cs[0].input(s.sim.frogs[0],0,true,false,false,s.sim,tacticalState(s.rules.view(0)));chosen.add(s.cs[0].tactics.target!);}assert.deepEqual([...chosen].sort(),[1,2]);});
